# --- your code ---
class WildcardDictionary:
    def __init__(self) -> None:
        self.root = {}                   # node = {letter: child}; "$" marks the end of a word

    def add(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True

    def match(self, pattern: str) -> bool:
        def dfs(node: dict, i: int) -> bool:
            if i == len(pattern):
                return "$" in node       # a prefix alone is not a word
            ch = pattern[i]
            if ch == ".":                # wildcard: any child may continue the match
                return any(dfs(kid, i + 1) for key, kid in node.items() if key != "$")
            return ch in node and dfs(node[ch], i + 1)

        return dfs(self.root, 0)


# --- provided: do not edit ---
def run_dictionary(ops: list[list]) -> list:
    words = WildcardDictionary()
    return [getattr(words, name)(*args) for name, *args in ops]
